class RequestBuilder {
    var url: String = ""
    private val headers = mutableMapOf<String, String>()

    fun header(name: String, value: String) { headers[name] = value }

    fun build() = Request(url, headers.toMap())   // immutable snapshot
}

data class Request(val url: String, val headers: Map<String, String>)

fun request(block: RequestBuilder.() -> Unit): Request =
    RequestBuilder().apply(block).build()

class Route(val path: String) {
    val children = mutableListOf<Route>()

    operator fun String.invoke(init: Route.() -> Unit) {
        children += Route(this).apply(init)
    }
}

fun routes(init: Route.() -> Unit) = Route("/").apply(init)

val tree = routes {
    "users" {
        "profile" { }
        "settings" { }
    }
